        add(hi05);

        MethodConfig q01q05 = m;
        q01q05.variant_name = "q01q05";
        q01q05.quantile_swap_low = 0.01;
        q01q05.quantile_swap_high = 0.05;
        q01q05.timesync_quantile = q01q05.quantile_swap_low;
        add(q01q05);

        MethodConfig tight = m;
