        tight.quantile_swap_jitter_enter_us = 150.0;
        tight.quantile_swap_jitter_exit_us = 90.0;
        tight.quantile_swap_iqr_enter_us = 300.0;
        tight.quantile_swap_iqr_exit_us = 200.0;
